defmodule ForemanAgent.Env.Overlay do
  @moduledoc """
  Generates the two files the agent layers over a repo's devcontainer:

  - a compose overlay that strips published ports, turns off restart
    policies (the agent orders starts after a reboot, once secrets are back
    on tmpfs), labels every service with the environment, and mounts the
    secrets directory and the Tailscale state volume
  - an override devcontainer.json that appends the overlay to
    `dockerComposeFile` (with absolute paths) and drops `initializeCommand`

  The YAML is written by hand: the structure is fixed, every scalar is
  emitted as a JSON string (valid YAML), and compose's `!reset` tag has no
  equivalent in a generic encoder.
  """

  @tailscale_volume "foreman-tailscale"

  @type params :: %{
          env_id: String.t(),
          slug: String.t(),
          services: [String.t()],
          devcontainer_service: String.t(),
          secrets_dir: Path.t(),
          tailscale: %{enabled: boolean()},
          limits: map()
        }

  @spec compose(params()) :: String.t()
  def compose(params) do
    tailscale? = params.tailscale[:enabled] == true

    services =
      Enum.map(params.services, fn service ->
        [
          "  ",
          q(service),
          ":\n",
          "    ports: !reset []\n",
          "    restart: \"no\"\n",
          "    labels:\n",
          "      \"foreman.env_id\": ",
          q(params.env_id),
          "\n",
          "      \"foreman.slug\": ",
          q(params.slug),
          "\n",
          if(service == params.devcontainer_service,
            do: devcontainer_service(params, tailscale?),
            else: []
          )
        ]
      end)

    volumes = if tailscale?, do: ["volumes:\n  ", q(@tailscale_volume), ": {}\n"], else: []

    IO.iodata_to_binary([
      "# Generated by Foreman for ",
      params.slug,
      ". Rewritten on every start; don't edit.\n",
      "services:\n",
      services,
      volumes
    ])
  end

  defp devcontainer_service(params, tailscale?) do
    env =
      [{"FOREMAN_ENV", params.slug}] ++
        if(tailscale?, do: [{"TS_HOSTNAME", params.slug}], else: [])

    [
      "    environment:\n",
      Enum.map(env, fn {k, v} -> ["      ", q(k), ": ", q(v), "\n"] end),
      "    volumes:\n",
      "      - type: bind\n",
      "        source: ",
      q(params.secrets_dir),
      "\n",
      "        target: \"/run/foreman\"\n",
      "        read_only: true\n",
      "        bind:\n",
      "          create_host_path: false\n",
      if(tailscale?,
        do: [
          "      - type: volume\n",
          "        source: ",
          q(@tailscale_volume),
          "\n",
          "        target: \"/var/lib/tailscale\"\n"
        ],
        else: []
      ),
      limits(params.limits)
    ]
  end

  defp limits(limits) do
    [
      case limits[:cpus] do
        nil -> []
        cpus -> ["    cpus: ", number(cpus), "\n"]
      end,
      case limits[:memory_mb] do
        nil -> []
        mb -> ["    mem_limit: ", q("#{mb}m"), "\n"]
      end
    ]
  end

  defp number(n) when is_integer(n), do: Integer.to_string(n)
  defp number(n) when is_float(n), do: :erlang.float_to_binary(n, [:short])

  defp q(value) when is_binary(value), do: JSON.encode!(value)

  @doc """
  The override devcontainer.json: the repo's config with
  `dockerComposeFile` replaced by absolute paths plus the overlay, and
  without `initializeCommand`, which the devcontainer CLI runs on the box
  itself rather than in a container.
  """
  @spec override_config(map(), keyword()) :: map()
  def override_config(config, opts) do
    files = Keyword.fetch!(opts, :compose_files) ++ [Keyword.fetch!(opts, :overlay_path)]

    config
    |> Map.put("dockerComposeFile", files)
    |> Map.delete("initializeCommand")
  end

  @doc "Options for the Foreman feature, passed with --additional-features."
  @spec feature_options(map()) :: map()
  def feature_options(tailscale), do: %{"tailscale" => tailscale[:enabled] == true}

  def tailscale_volume, do: @tailscale_volume
end
